// Custom Node/Edge Type Definition Pattern
import type { BuiltInNode, BuiltInEdge } from '@xyflow/react';

export type CustomNodeType = BuiltInNode | NumberNode | TextNode;
export type CustomEdgeType = BuiltInEdge | EditableEdge;

// Usage with hooks:
const store = useStoreApi<CustomNodeType, CustomEdgeType>();
const reactFlow = useReactFlow<CustomNodeType, CustomEdgeType>();

// Viewport Management Pattern
import { useViewport, useOnViewportChange } from '@xyflow/react';

function ViewportHandler() {
  const { x, y, zoom } = useViewport();

  useOnViewportChange({
    onStart: (viewport) => console.log('start', viewport),
    onChange: (viewport) => console.log('change', viewport),
    onEnd: (viewport) => console.log('end', viewport),
  });

  return null;
}

// Fit View Utility
import { getViewportForBounds } from '@xyflow/react';
const { x, y, zoom } = getViewportForBounds(bounds, width, height, minZoom, maxZoom);

// Zustand with Dexie Storage Pattern
import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import Dexie from 'dexie';

const db = new Dexie('CanvasStore');

interface CanvasStore {
  nodes: Node[];
  edges: Edge[];
  setNodes: (nodes: Node[]) => void;
}

export const useCanvasStore = create<CanvasStore>()(
  persist(
    (set) => ({
      nodes: [],
      edges: [],
      setNodes: (nodes) => set({ nodes }),
    }),
    {
      name: 'canvas-storage',
      storage: createJSONStorage(() => ({
        getItem: async (name) => await db.table(name).toArray(),
        setItem: async (name, value) => {
          await db.table(name).clear();
          await db.table(name).add(value);
        },
        removeItem: async (name) => {
          await db.table(name).clear();
        },
      })),
    },
  ),
);
